 v=[("la obra","a peça","Soa como “la O-bra”.","🎭"),("el ensayo","o ensaio","Soa como “el en-SA-yo”.","🔁"),("la escenografía","o cenário","Soa como “la es-se-no-gra-FÍ-a”.","🖼️"),("la dirección","a direção","Soa como “la di-rek-SION”.","🎬"),("el telón","a cortina de cena","Soa como “el te-LÓN”.","🎭"),("el aplauso","o aplauso","Soa como “el a-PLAU-so”.","👏")],
 chat=["P: Pasa, pasa, estamos en pleno ensayo de «Bodas de sangre», de Lorca. | Entre, entre, estamos em pleno ensaio de «Bodas de sangue», de Lorca.",
  "Y: Se nota la tensión en el escenario. ¿Siempre ensayan tanto? | Nota-se a tensão no palco. Sempre ensaiam tanto?",
  "P: Todos los días. Hoy el director cambió la escenografía en el último ensayo y hay que adaptarse. | Todos os dias. Hoje o diretor mudou o cenário no último ensaio e é preciso se adaptar.",
  "Y: ¿Qué ha cambiado exactamente? | O que mudou exatamente?",
  "P: Quitó los muebles y puso una luna enorme de tela. Ahora el telón cae más lento y todo parece un sueño. | Tirou os móveis e colocou uma lua enorme de pano. Agora a cortina cai mais devagar e tudo parece um sonho.",
  "Y: Es muy dramático, como la propia obra. | É muito dramático, como a própria peça.",
  "P: Eso buscaba. Cuando termine el último acto, el público tiene que quedarse en silencio unos segundos antes del aplauso. | Era isso que buscava. Quando terminar o último ato, o público tem que ficar em silêncio por alguns segundos antes do aplauso.",
  "Y: Lucía, dime la verdad: ¿es verdad que viste a un hombre de traje gris aquí? | Lucía, diga-me a verdade: é verdade que viu um homem de terno cinza aqui?",
  "P: Sí, estaba sentado al fondo, tomando notas, aunque no era crítico de teatro. | Sim, estava sentado ao fundo, tomando notas, embora não fosse crítico de teatro.",
  "Y: ¿Y qué escribía? | E o que escrevia?",
  "P: No lo sé, pero después del ensayo vi cómo hablaba con Carmen en el pasillo. Mañana te cuento qué dijeron. | Não sei, mas depois do ensaio vi como falava com Carmen no corredor. Amanhã conto o que disseram."],
 tap=[("¿Qué obra ensayan?","Que peça ensaiam?",["«Bodas de sangre»","«Don Quijote»","«La Celestina»"],0,0,"P: “«Bodas de sangre», de Lorca”"),
  ("¿Qué puso el director en el escenario?","O que o diretor pôs no palco?",["Un árbol real","Una luna enorme de tela","Un piano antiguo"],1,4,"P: “puso una luna enorme de tela”"),
  ("¿Con quién habló el hombre de traje gris?","Com quem falou o homem de terno cinza?",["Con Pablo","Con Javier","Con Carmen"],2,10,"P: “hablaba con Carmen en el pasillo”")],
 swap=("Describir: «hoy ha cambiado…» (pretérito perfecto) y «ayer cambió…» (indefinido). 🎓 DELE B2: describir cambios y acontecimientos.",
  [("Perfecto vs. indefinido",[("Hoy el director ha cambiado","Hoje o diretor mudou"),("Ayer el director cambió","Ontem o diretor mudou"),("Esta semana hemos ensayado","Esta semana ensaiamos")],[("la escenografía","o cenário"),("el final de la obra","o final da peça"),("toda la escena","toda a cena")],"."),
   ("Antes de que / cuando",[("Antes de que empiece el acto","Antes que comece o ato"),("Cuando termine la función","Quando terminar a sessão"),("Hasta que caiga el telón","Até que caia a cortina")],[("el público guarda silencio","o público guarda silêncio"),("habrá un aplauso largo","haverá um aplauso longo"),("nadie se mueve","ninguém se mexe")],".")]),
 chat2=["Y: ¿Cuánto tiempo falta para el estreno? | Quanto tempo falta para a estreia?",
  "P: Solo una semana. Tenemos que dejarlo todo listo antes de que lleguen los críticos. | Só uma semana. Temos que deixar tudo pronto antes que cheguem os críticos.",
  "Y: ¿Y estás nerviosa? | E você está nervosa?",
  "P: Un poco, pero los nervios ayudan a actuar mejor. | Um pouco, mas os nervos ajudam a atuar melhor.",
  "Y: ¿Puedo venir a la función? | Posso ir à sessão?",
  "P: Claro, te guardo una butaca delante, para que no te pierdas nada. | Claro, guardo uma poltrona na frente, para que você não perca nada."],
 slang=("Lucía",["🎭","#AE3EC9"],["F: Tía, estoy hecha polvo, los ensayos me están matando. | Amiga, estou destruída, os ensaios estão me matando.","Y: Anda, que no es para tanto. Seguro que saldrá genial. | Ora, não é para tanto. Com certeza vai sair ótimo.","F: Ya, pero el director nos da mucha caña. | Pois é, mas o diretor pega pesado com a gente.","Y: Tú aguanta, que después de la función nos vamos de cañas. | Aguente firme, que depois da sessão vamos tomar cerveja.","F: Eso sí que es un planazo. Me lo pido. | Isso sim é um programão. Eu topo.","Y: Pues dalo por hecho, y el primero va por mi cuenta. | Então considere combinado, e o primeiro é por minha conta."],
  {"tía":"amiga, mulher (Espanha)","hecha polvo":"destruída, esgotada","nos da mucha caña":"pega pesado com a gente","de cañas":"tomar cerveja (Espanha)","planazo":"programão, plano ótimo"},["hecha polvo","planazo"]),
